namespace Sessions.Core;

// Window placement in virtual-screen coordinates, plus the SW_* show command.
public sealed record Placement(int X, int Y, int Width, int Height, int ShowCmd);

using System.Text.Json.Serialization;

namespace Sessions.Core;

// A session entry: something to launch and, optionally, where to place it.
// Serialized polymorphically on the "adapter" discriminator.
[JsonPolymorphic(TypeDiscriminatorPropertyName = "adapter")]
[JsonDerivedType(typeof(GenericEntry), "generic")]
public abstract record Entry(string DisplayName, Placement? Placement);

// Launches an arbitrary executable with optional command-line arguments.
public sealed record GenericEntry(string DisplayName, Placement? Placement, string ExePath, string Arguments)
    : Entry(DisplayName, Placement);

using System.Text.Json;
using Sessions.Core;

namespace Sessions.Tests;

public class EntryTests
{
    [Fact]
    public void GenericEntry_RoundTrips_ThroughBaseType()
    {
        Entry original = new GenericEntry(
            DisplayName: "Notepad",
            Placement: new Placement(100, 200, 800, 600, 1),
            ExePath: @"C:\Windows\notepad.exe",
            Arguments: "--example \"quoted arg\"");

        string json = JsonSerializer.Serialize(original);
        Entry? restored = JsonSerializer.Deserialize<Entry>(json);

        Assert.Equal(original, restored);
        Assert.IsType<GenericEntry>(restored);
    }
}

using System.Collections.Generic;

namespace Sessions.Core;

// A named, persisted collection of entries to launch together.
public sealed record Session(
    int SchemaVersion,
    Guid Id,
    string Name,
    DateTimeOffset CreatedAt,
    IReadOnlyList<Entry> Entries)
{
    // Bump when the on-disk shape changes; Load rejects anything it doesn't know.
    public const int CurrentSchemaVersion = 1;
}

using System.IO;
using System.Text.Json;

namespace Sessions.Core;

// Persists sessions as one JSON file per id under a directory.
// Writes are atomic: a temp file is written, then moved over the target.
public sealed class JsonSessionStore
{
    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web)
    {
        WriteIndented = true,
    };

    private readonly string _directory;

    public JsonSessionStore(string directory)
    {
        _directory = directory ?? throw new ArgumentNullException(nameof(directory));
    }

    // %APPDATA%\Sessions\sessions
    public static string DefaultDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
        "Sessions",
        "sessions");

    public void Save(Session session)
    {
        ArgumentNullException.ThrowIfNull(session);

        Directory.CreateDirectory(_directory);

        string target = PathFor(session.Id);
        string temp = target + ".tmp";

        byte[] bytes = JsonSerializer.SerializeToUtf8Bytes(session, Options);
        File.WriteAllBytes(temp, bytes);
        File.Move(temp, target, overwrite: true);
    }

    public Session Load(Guid id)
    {
        string path = PathFor(id);
        string json = File.ReadAllText(path);

        Session? session;
        try
        {
            session = JsonSerializer.Deserialize<Session>(json, Options);
        }
        catch (JsonException ex)
        {
            throw new InvalidDataException($"Session file '{path}' contains malformed JSON.", ex);
        }

        if (session is null)
        {
            throw new InvalidDataException($"Session file '{path}' deserialized to null.");
        }

        if (session.SchemaVersion != Session.CurrentSchemaVersion)
        {
            throw new InvalidDataException(
                $"Session file '{path}' has unknown schema version {session.SchemaVersion}; " +
                $"expected {Session.CurrentSchemaVersion}.");
        }

        return session;
    }

    private string PathFor(Guid id) => Path.Combine(_directory, id.ToString("D") + ".json");
}

using System.Text.Json;
using Sessions.Core;

namespace Sessions.Tests;

public class SessionTests
{
    [Fact]
    public void Session_WithEntries_RoundTrips()
    {
