namespace Sessions.Core;

// A top-level window the user could reasonably place, with what we could learn
// about its owning process. ExePath/CommandLine are null when they couldn't be
// read; UnsupportedReason explains why rather than guessing a value.
public sealed record WindowInfo(nint Handle, string Title, uint ProcessId)
{
    // Full path to the owning process's executable, or null if unreadable.
    public string? ExePath { get; init; }

    // Why this window can't be captured (e.g. exe path unreadable). Null = fine.
    public string? UnsupportedReason { get; init; }

    // The process command line, or null if empty/unreadable (adapters decide
    // whether a missing command line is an error).
    public string? CommandLine { get; init; }

    // The parent process id, or null if it couldn't be read.
    public uint? ParentProcessId { get; init; }
}

using System.Management;
using Windows.Win32;
using Windows.Win32.Foundation;
using Windows.Win32.System.Threading;

namespace Sessions.Core;

// Reads what we can about a process behind a window: its executable path (Win32
// API) and its command line + parent pid (WMI). Each returns null on failure
// rather than throwing, so one unreadable process never sinks enumeration.
internal static class ProcessDetails
{
    // Full image path via the Win32 API. On failure, exePath is null and
    // reason explains why (no guessing a path).
    public static (string? ExePath, string? Reason) ReadExePath(uint processId)
    {
        using var handle = PInvoke.OpenProcess(
            PROCESS_ACCESS_RIGHTS.PROCESS_QUERY_LIMITED_INFORMATION,
            bInheritHandle: false,
            processId);

        if (handle.IsInvalid)
        {
            return (null, $"OpenProcess failed for pid {processId} (likely elevated or protected).");
        }

        uint size = 1024;
        unsafe
        {
            Span<char> buffer = stackalloc char[(int)size];
            fixed (char* p = buffer)
            {
                if (!PInvoke.QueryFullProcessImageName(handle, PROCESS_NAME_FORMAT.PROCESS_NAME_WIN32, new PWSTR(p), ref size))
                {
                    return (null, $"QueryFullProcessImageName failed for pid {processId}.");
                }

                return (new string(p, 0, (int)size), null);
            }
        }
    }

    // CommandLine and ParentProcessId from Win32_Process. An empty command line
    // comes back as null; adapters decide whether that's an error.
    public static (string? CommandLine, uint? ParentProcessId) ReadWmi(uint processId)
    {
        try
        {
            using var searcher = new ManagementObjectSearcher(
                $"SELECT CommandLine, ParentProcessId FROM Win32_Process WHERE ProcessId = {processId}");

            foreach (ManagementBaseObject mo in searcher.Get())
            {
                using (mo)
                {
                    string? commandLine = mo["CommandLine"] as string;
                    if (string.IsNullOrEmpty(commandLine))
                    {
                        commandLine = null;
                    }

                    uint? parentProcessId = mo["ParentProcessId"] is { } parent
                        ? Convert.ToUInt32(parent)
                        : null;

                    return (commandLine, parentProcessId);
                }
            }
        }
        catch (ManagementException)
        {
            // WMI unavailable or access denied — leave both unknown.
        }

        return (null, null);
    }
}

using System.Collections.Generic;
using Windows.Win32;
using Windows.Win32.Foundation;
using Windows.Win32.Graphics.Dwm;
using Windows.Win32.UI.WindowsAndMessaging;

namespace Sessions.Core;

// Enumerates the "real" top-level windows: visible, titled, unowned, not tool
// windows, not cloaked, not our own, and not the desktop shell. These are the
// ones worth offering the user to capture/place, enriched with process details.
public static class WindowEnumerator
{
    public static IReadOnlyList<WindowInfo> Enumerate()
    {
        uint ownProcessId = (uint)Environment.ProcessId;
        List<WindowInfo> windows = new();

        PInvoke.EnumWindows(
            (HWND hwnd, LPARAM _) =>
            {
                if (TryDescribe(hwnd, ownProcessId, out WindowInfo info))
                {
                    windows.Add(info);
                }

                return true; // keep enumerating
            },
            default);

        return windows;
    }

    private static bool TryDescribe(HWND hwnd, uint ownProcessId, out WindowInfo info)
    {
        info = default!;

        if (!PInvoke.IsWindowVisible(hwnd))
        {
            return false;
        }

        // Skip owned windows (dialogs, tool palettes, etc.).
        if (!PInvoke.GetWindow(hwnd, GET_WINDOW_CMD.GW_OWNER).IsNull)
        {
            return false;
        }

        // Skip tool windows, which aren't meant to appear in the alt-tab list.
        // The extended style flags all fit in the low 32 bits, so GetWindowLong is enough.
        const uint WS_EX_TOOLWINDOW = 0x00000080;
        int exStyle = PInvoke.GetWindowLong(hwnd, WINDOW_LONG_PTR_INDEX.GWL_EXSTYLE);
        if (((uint)exStyle & WS_EX_TOOLWINDOW) != 0)
        {
            return false;
        }

        // Skip cloaked windows (e.g. suspended UWP apps, virtual-desktop hidden).
        if (IsCloaked(hwnd))
        {
            return false;
        }

        string title = GetTitle(hwnd);
        if (title.Length == 0)
        {
            return false;
        }

        // Skip the desktop shell's own window.
        if (title == "Program Manager")
        {
            return false;
        }

        uint processId;
        unsafe
        {
            _ = PInvoke.GetWindowThreadProcessId(hwnd, &processId);
        }

        // Skip our own windows.
        if (processId == ownProcessId)
        {
            return false;
        }

        (string? exePath, string? reason) = ProcessDetails.ReadExePath(processId);
        (string? commandLine, uint? parentProcessId) = ProcessDetails.ReadWmi(processId);

        info = new WindowInfo(hwnd, title, processId)
        {
            ExePath = exePath,
            UnsupportedReason = reason,
